'use strict';

// MODULES //

var Float64Array = require( '@stdlib/array/float64' );
var Uint32Array = require( '@stdlib/array/uint32' );
var isCollection = require( '@stdlib/assert/is-collection' );
var isNonNegativeInteger = require( '@stdlib/assert/is-nonnegative-integer' ).isPrimitive;
var UINT32_MAX = require( '@stdlib/constants/uint32/max' );
var format = require( '@stdlib/string/format' );
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var addon = require( './../src/addon.node' );


// VARIABLES //

// Define the maximum seed: 2^32-1 => 4294967295
var MAX_SEED = UINT32_MAX >>> 0; // asm type annotation


// MAIN //

/**
* Generates a sequence of pseudorandom 32-bit unsigned integers using the native PCG32 implementation.
*
* @private
* @param {PRNGSeedPCG32} seed - generator seed
* @param {NonNegativeInteger} n - number of values to generate
* @throws {TypeError} first argument must be either a nonnegative integer less than or equal to the maximum 32-bit unsigned integer or an array-like object containing nonnegative integer values less than or equal to the maximum 32-bit unsigned integer
* @throws {RangeError} first argument must be a nonnegative integer less than or equal to the maximum 32-bit unsigned integer
* @throws {TypeError} second argument must be a nonnegative integer
* @returns {Uint32Array} pseudorandom integers
*
* @example
* var out = pcg32( 1234, 10 );
* // returns <Uint32Array>
*/
function pcg32( seed, n ) {
	var out;
	if ( isNonNegativeInteger( seed ) ) {
		if ( seed > MAX_SEED ) {
			throw new RangeError( format( 'invalid argument. First argument must be a nonnegative integer less than or equal to the maximum 32-bit unsigned integer. Option: `%u`.', 'seed', seed ) );
		}
		seed = [ seed ];
	} else if ( !isCollection( seed ) || seed.length < 1 ) {
		throw new TypeError( format( 'invalid argument. First argument must be either a nonnegative integer less than or equal to the maximum 32-bit unsigned integer or an array-like object containing nonnegative integer values less than or equal to the maximum 32-bit unsigned integer. Option: `%s`.', 'seed', seed ) );
	}
	if ( !isNonNegativeInteger( n ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be a nonnegative integer. Value: `%d`.', n ) );
	}
	out = new Uint32Array( n );
	addon( new Uint32Array( seed ), out );
	return out;
}

/**
* Generates a sequence of normalized pseudorandom double-precision floating-point numbers using the native PCG32 implementation.
*
* @private
* @param {PRNGSeedPCG32} seed - generator seed
* @param {NonNegativeInteger} n - number of values to generate
* @throws {TypeError} first argument must be either a nonnegative integer less than or equal to the maximum 32-bit unsigned integer or an array-like object containing nonnegative integer values less than or equal to the maximum 32-bit unsigned integer
* @throws {RangeError} first argument must be a nonnegative integer less than or equal to the maximum 32-bit unsigned integer
* @throws {TypeError} second argument must be a nonnegative integer
* @returns {Float64Array} pseudorandom numbers on the interval `[0,1)`
*
* @example
* var out = pcg32.normalized( 1234, 10 );
* // returns <Float64Array>
*/
function normalized( seed, n ) {
	var out;
	if ( isNonNegativeInteger( seed ) ) {
		if ( seed > MAX_SEED ) {
			throw new RangeError( format( 'invalid argument. First argument must be a nonnegative integer less than or equal to the maximum 32-bit unsigned integer. Option: `%u`.', 'seed', seed ) );
		}
		seed = [ seed ];
	} else if ( !isCollection( seed ) || seed.length < 1 ) {
		throw new TypeError( format( 'invalid argument. First argument must be either a nonnegative integer less than or equal to the maximum 32-bit unsigned integer or an array-like object containing nonnegative integer values less than or equal to the maximum 32-bit unsigned integer. Option: `%s`.', 'seed', seed ) );
	}
	if ( !isNonNegativeInteger( n ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be a nonnegative integer. Value: `%d`.', n ) );
	}
	out = new Float64Array( n );
	addon.normalized( new Uint32Array( seed ), out );
	return out;
}

setReadOnly( pcg32, 'normalized', normalized );


// EXPORTS //

module.exports = pcg32;
